// MSCD v2.4 mockup: sample data + derivation helpers (fictional organisation)
export const TODAY_S = '2026-09-29';
const TODAY = new Date(TODAY_S + 'T00:00:00');
export const P = s => new Date(s + 'T00:00:00');
export const dd = s => Math.round((P(s) - TODAY) / 864e5);
export const addD = (s, n) => { const d = P(s); d.setDate(d.getDate() + n); return d.toISOString().slice(0, 10); };
const MON = { en: ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'], id: ['Jan','Feb','Mar','Apr','Mei','Jun','Jul','Agu','Sep','Okt','Nov','Des'] };
export const fmt = (s, l) => { if (!s) return '-'; const d = P(s); return d.getDate() + ' ' + MON[l || 'en'][d.getMonth()] + ' ' + d.getFullYear(); };

